package com.muxigame.city;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsOpportunities {
 @GameTest(template="empty") public static void poorHunterTakesRealVacantArtisanJobWithoutNewAssets(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var hunter=f.r.state.people.values().stream().filter(p->p.role==RuralRules.Role.HUNTER).findFirst().orElseThrow();var family=f.r.state.families.get(hunter.family);var old=f.r.state.people.values().stream().filter(p->p.role==RuralRules.Role.ARTISAN&&f.village.residents.contains(p.id)).findFirst().orElseThrow();old.dead=true;hunter.nourishment=19;for(var stock:f.r.stocks(family.id)){stock.wheat=stock.bread=0;RuralMeat.clear(stock);}for(var id:family.members)f.e.state.accounts.put(CityEconomy.person(id),0L);long cash=f.t.money(f.s);int people=f.r.state.people.size();CityOpportunities.daily(f.s,f.village,family);h.assertTrue(hunter.role==RuralRules.Role.ARTISAN&&f.m.state.workers.get(hunter.id).enabled,"Income pressure can trigger voluntary transfer to an existing basic job");h.assertTrue(f.r.state.sites.values().stream().filter(site->hunter.id.equals(site.worker)).count()==1&&f.r.state.people.size()==people&&f.t.money(f.s)==cash,"Exactly one workplace; no worker, inheritance or cash grant");}h.succeed();}
 @GameTest(template="empty") public static void selfEmployedBakerCanUseOwnedInputsBeforeDrawingOwnWage(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var baker=f.t.state.businesses.values().stream().filter(b->b.kind.equals("baker")).findFirst().orElseThrow();var client=f.r.state.families.values().stream().filter(v->v.city.equals(baker.city)&&!v.members.contains(baker.owner)).findFirst().orElseThrow();for(var stock:f.r.stocks(client.id)){stock.wheat=stock.bread=0;RuralMeat.clear(stock);}f.e.state.accounts.put(CityEconomy.person(client.members.getFirst()),100L);baker.stock[0].add(4,400);f.e.state.accounts.put(baker.account,0L);var owner=f.r.state.people.get(baker.owner);for(var id:f.r.state.families.get(owner.family).members)f.e.state.accounts.put(CityEconomy.person(id),0L);long cash=f.t.money(f.s),grain=f.t.grain(f.s);f.t.production(f.s,baker,0);h.assertTrue(baker.stock[0].count==0&&baker.stock[1].count==4,"Owner transforms real paid raw stock without an impossible self-pay prerequisite");h.assertTrue(f.t.money(f.s)==cash&&f.t.grain(f.s)==grain&&baker.wages==0,"No fake wage, no free material or currency");}h.succeed();}
 @GameTest(template="empty") public static void preparedFoodChoiceUsesOpportunityCostAndDailyPlanPersists(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);h.assertTrue(FoodMarketRules.buyPrepared(3,5,3,true)&&!FoodMarketRules.buyPrepared(3,9,3,true),"Household compares monetary saving with lost productive time");CityBaking.plan(f.s,f.city.id);var before=f.t.state.businesses.values().stream().filter(b->b.kind.equals("baker")).mapToInt(b->b.breadRemaining).toArray();CityBaking.plan(f.s,f.city.id);var after=f.t.state.businesses.values().stream().filter(b->b.kind.equals("baker")).mapToInt(b->b.breadRemaining).toArray();h.assertTrue(Arrays.equals(before,after)&&Arrays.stream(after).allMatch(n->n>=0&&n<=80),"One bounded forecast/day, no repeated random reroll");}h.succeed();}
}
